import json
from pathlib import Path
wanted = 'EXISTING-PACKAGE-MARKETPLACE-CHECKOUT'
paths = sorted(Path('world/pages').glob('missions-*.json'))
matches = []
def scan(node):
    if isinstance(node, dict):
        if node.get('mission_id') == wanted and 'status' in node:
            matches.append({key: node.get(key) for key in ('mission_id', 'status', 'evidence')})
        for value in node.values():
            scan(value)
    elif isinstance(node, list):
        for value in node:
            scan(value)
for path in paths:
    scan(json.loads(path.read_text()))
out = Path('products/services/sqlite-lemon-squeezy/l369-mission-evidence.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps({'pages_read': [str(path) for path in paths], 'matches': matches}, indent=2) + '\n')
print(out.read_text())
